export function isInCheck(board: Board, player: Player): boolean {
  const generalPos = findGeneralPosition(board, player);

  // Standard check: an opponent piece can capture the general
  if (isSquareAttackedBy(board, generalPos, opponent(player))) {
    return true;
  }

  // Flying-general check: both generals facing each other on same column
  if (flyingGeneralTarget(board) === player) {
    return true;
  }

  return false;
}
```

### How it works

1. **`findGeneralPosition(board, player)`** — scans the 10×9 board for `player`'s general piece (type `'general'`), returns its `Position`.

2. **`isSquareAttackedBy(board, pos, attacker)`** — iterates every board square, and for each piece owned by `attacker`, generates its **raw moves** via `getRawMoves()`. If any raw move targets the general's square, returns `true`. Raw moves already encode all piece-specific rules (chariot line-of-sight, cannon screen jumps, knight leg-blocks, elephant eye-blocks, palace/river constraints, etc.).

3. **`flyingGeneralTarget(board)`** — detects if both generals share the same column with no intervening pieces (the "flying general" / 将帅照面 rule). Returns the player whose general is "behind" (higher row), or `null` if not facing.

